function Brand({ dark = false }: { dark?: boolean }) {
  return <div className="flex items-center gap-2.5"><div className={`grid size-9 place-items-center rounded-xl ${dark ? 'bg-[#b8e3c2] text-[#173f36]' : 'bg-[#235d51] text-[#f4f0e3]'} shadow-sm`}><MessageCircle size={19} strokeWidth={2.4} /></div><span className={`font-display text-[20px] font-extrabold tracking-[-.04em] ${dark ? 'text-[#f1eadc]' : 'text-[#173f36]'}`}>saha<span className={dark ? 'text-[#b8e3c2]' : 'text-[#d27f46]'}>ai</span></span></div>;
}

function Avatar({ initials, tone = 'green', size = 'md' }: { initials: string; tone?: string; size?: 'sm' | 'md' | 'lg' }) {
  const colors: Record<string, string> = { green: 'bg-[#d4e8d8] text-[#245d4f]', clay: 'bg-[#f2d8c6] text-[#954b2d]', blue: 'bg-[#d7e6e8] text-[#286270]', plum: 'bg-[#e6dbea] text-[#664d75]', gold: 'bg-[#f5e3b2] text-[#80601d]' };
  return <div data-testid={`avatar-${initials}`} className={`grid shrink-0 place-items-center rounded-full font-display font-bold ${colors[tone] ?? colors.green} ${size === 'sm' ? 'size-7 text-[10px]' : size === 'lg' ? 'size-12 text-sm' : 'size-9 text-xs'}`}>{initials}</div>;
}

function ChannelMark({ channel }: { channel: Channel }) {
  return <span className={`inline-grid size-5 place-items-center rounded-md ${channel === 'WhatsApp' ? 'bg-[#d8f0dc] text-[#287550]' : 'bg-[#f6dbe8] text-[#a14472]'}`}>{channel === 'WhatsApp' ? <MessageCircle size={12} /> : <Instagram size={12} />}</span>;
}

function Button({ children, variant = 'primary', className = '', onClick, type = 'button', disabled = false }: { children: React.ReactNode; variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; className?: string; onClick?: () => void; type?: 'button' | 'submit'; disabled?: boolean }) {
  const variants = { primary: 'bg-[#235d51] text-[#f8f2e7] shadow-[0_5px_14px_rgba(35,93,81,.18)] hover:bg-[#194c42]', secondary: 'border border-[#d9d4c8] bg-[#fbf8f0] text-[#28574d] hover:bg-[#f3eddf]', ghost: 'text-[#63766f] hover:bg-[#ece9de] hover:text-[#28574d]', danger: 'border border-[#e9c5be] bg-[#fdf3f0] text-[#ad4b3c] hover:bg-[#fae8e3]' };
  return <button data-testid="button-action" type={type} disabled={disabled} onClick={onClick} className={`focus-ring inline-flex items-center justify-center gap-2 rounded-xl px-3.5 py-2.5 text-[13px] font-bold transition-all duration-200 active:translate-y-px disabled:cursor-not-allowed disabled:opacity-50 ${variants[variant]} ${className}`}>{children}</button>;
}

function Badge({ children, tone = 'neutral' }: { children: React.ReactNode; tone?: 'green' | 'gold' | 'blue' | 'red' | 'neutral' }) {
  const tones = { green: 'bg-[#e0f1e2] text-[#2c7154]', gold: 'bg-[#f8ebc7] text-[#8b6824]', blue: 'bg-[#e1eef0] text-[#34707a]', red: 'bg-[#f7e2dc] text-[#a25243]', neutral: 'bg-[#eeece5] text-[#66766f]' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold ${tones[tone]}`}>{children}</span>;
}

