function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="page-enter mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[.18em] text-[#b66c43]">{eyebrow ?? 'Workspace'}</div><h1 data-testid="text-page-title" className="font-display text-[30px] font-extrabold tracking-[-.05em] text-[#1b4a3f] md:text-[35px]">{title}</h1>{description && <p className="mt-2 max-w-xl text-[13px] leading-6 text-[#71847b]">{description}</p>}</div>{action}</div>;
}

function MetricCard({ label, value, change, detail, icon: Icon, tone = 'green' }: { label: string; value: string; change: string; detail: string; icon: typeof TrendingUp; tone?: string }) {
  return <div className="page-enter rounded-2xl border border-[#e4ded1] bg-[#fbf9f3] p-5 shadow-[var(--shadow-soft)]"><div className="mb-5 flex items-start justify-between"><div className={`grid size-9 place-items-center rounded-xl ${tone === 'gold' ? 'bg-[#f8eac5] text-[#8a6326]' : tone === 'blue' ? 'bg-[#deedef] text-[#2c7078]' : 'bg-[#dcecdf] text-[#2b6a56]'}`}><Icon size={17} /></div><span className="flex items-center gap-1 text-[11px] font-bold text-[#3d8966]"><ArrowUpRight size={13} />{change}</span></div><div className="font-display text-[29px] font-extrabold tracking-[-.06em] text-[#1b4a3f]">{value}</div><div className="mt-1 text-xs font-bold text-[#536c62]">{label}</div><div className="mt-3 text-[11px] text-[#92a097]">{detail}</div></div>;
}

