  return <SettingsLayout title="Plan & billing" description="Simple plans for businesses building relationships at their own pace. You are currently on Studio." action={<Button variant="secondary"><Download size={14} />Download invoices</Button>}><div className="mb-5 rounded-2xl border border-[#b9d8bd] bg-[#e8f2e4] p-5"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><div className="flex items-center gap-2"><Badge tone="green">Current plan</Badge><span className="font-display text-[18px] font-extrabold text-[#28574d]">Studio</span></div><p className="mt-2 text-xs text-[#688677]">Your next renewal is 12 June 2024 · Visa ending 4242</p></div><div className="text-left md:text-right"><div className="font-mono-custom text-[21px] font-bold text-[#28574d]">SAR 349</div><div className="text-[10px] text-[#7a9486]">per month</div></div></div></div><div className="grid gap-4 lg:grid-cols-3">{plans.map((plan, i) => <button data-testid={`button-plan-${plan.name.toLowerCase()}`} key={plan.name} onClick={() => setSelected(plan.name)} className={`relative text-left rounded-2xl border p-5 transition-all ${selected === plan.name ? 'border-[#70a77e] bg-[#eef5e9] shadow-[0_6px_22px_rgba(54,113,80,.1)]' : 'border-[#e3ddd2] bg-[#fbf9f3] hover:border-[#b5cbb8]'}`}>{i === 1 && <span className="absolute -top-3 left-5 rounded-full bg-[#cc7c4c] px-2.5 py-1 text-[9px] font-bold uppercase tracking-wider text-white">Most chosen</span>}<div className="flex items-start justify-between"><div><div className="font-display text-[17px] font-extrabold text-[#315f54]">{plan.name}</div><div className="mt-1 text-[11px] text-[#82938b]">{plan.desc}</div></div><span className={`grid size-5 place-items-center rounded-full border-2 ${selected === plan.name ? 'border-[#4f936d] bg-[#4f936d] text-white' : 'border-[#cbd5cc]'}`}>{selected === plan.name && <Check size={12} />}</span></div><div className="my-5 font-mono-custom text-[25px] font-bold tracking-[-.05em] text-[#28574d]">SAR {plan.price}<span className="font-sans text-xs font-medium tracking-normal text-[#83938b]"> / month</span></div><div className="space-y-2 border-t border-[#e6e0d5] pt-4">{plan.features.map(f => <div key={f} className="flex items-center gap-2 text-xs text-[#61796f]"><Check size={14} className="text-[#4f936d]" />{f}</div>)}</div>{selected === plan.name && <div className="mt-5 rounded-lg bg-[#d5e9d3] py-2 text-center text-[11px] font-bold text-[#39745a]">{plan.name === 'Studio' ? 'Your active plan' : 'Switch to this plan'}</div>}</button>)}</div><div className="mt-5 rounded-2xl border border-[#e3ddd2] bg-[#fbf9f3] p-5"><div className="flex items-center justify-between"><div><h2 className="font-display text-[16px] font-extrabold text-[#315f54]">Billing history</h2><p className="mt-1 text-[11px] text-[#8c9b94]">Your latest SahaAI invoices</p></div><CreditCard size={18} className="text-[#91a29a]" /></div><div className="mt-4 divide-y divide-[#eee9df]">{['12 May 2024', '12 Apr 2024', '12 Mar 2024'].map((date, i) => <div key={date} className="flex items-center justify-between py-3 text-xs"><span className="font-bold text-[#59756a]">SahaAI Studio · {date}</span><span className="font-mono-custom text-[#6f877d]">SAR 349.00</span><button data-testid={`button-download-invoice-${i}`} className="text-[#b66c43]"><Download size={14} /></button></div>)}</div></div></SettingsLayout>;
