function AuthPage({ register = false }: { register?: boolean }) {
  const [, setLocation] = useLocation();
  const [showPassword, setShowPassword] = useState(false);
  return <div className="grain flex min-h-[100dvh] bg-[#f6f2e8]"><div className="hidden w-[47%] flex-col justify-between bg-[#173f36] p-10 text-[#f1eadc] lg:flex"><Brand dark /><div className="max-w-md"><div className="mb-5 flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.2em] text-[#9ec4b0]"><span className="size-2 rounded-full bg-[#b8e3c2]" />A calmer way to care</div><h1 className="font-display text-[54px] font-extrabold leading-[.98] tracking-[-.07em]">Keep the thread.<br /><span className="text-[#b8e3c2]">Grow the trust.</span></h1><p className="mt-6 max-w-sm text-[15px] leading-7 text-[#b3cdbf]">SahaAI gives small Gulf businesses the space to follow every conversation from first hello to lasting relationship.</p><div className="mt-10 flex items-center gap-3 text-xs text-[#9fbcaf]"><div className="flex -space-x-2"><Avatar initials="AA" tone="clay" size="sm" /><Avatar initials="MS" tone="blue" size="sm" /><Avatar initials="OK" tone="gold" size="sm" /></div><span>Loved by 240+ thoughtful teams</span></div></div><div className="flex items-center justify-between text-[10px] text-[#789e8e]"><span>Made for businesses across the Gulf</span><span>English · العربية</span></div></div><div className="flex flex-1 flex-col px-6 py-8 md:px-16 lg:px-20"><div className="lg:hidden"><Brand /></div><div className="mx-auto flex w-full max-w-[410px] flex-1 flex-col justify-center"><div className="mb-8 mt-10 lg:mt-0"><div className="mb-3 text-[10px] font-bold uppercase tracking-[.18em] text-[#b66c43]">{register ? 'Start your workspace' : 'Welcome back'}</div><h2 className="font-display text-[32px] font-extrabold tracking-[-.06em] text-[#1b4a3f]">{register ? 'A better inbox starts here.' : 'Good to see you again.'}</h2><p className="mt-2 text-sm text-[#7e9087]">{register ? 'Set up your studio in a few minutes. No credit card needed.' : 'Sign in to pick up exactly where your customers left you.'}</p></div><form onSubmit={e => { e.preventDefault(); setLocation('/app'); }} className="space-y-4"><label className="block"><span className="mb-2 block text-[11px] font-bold uppercase tracking-wider text-[#879890]">Work email</span><input data-testid="input-auth-email" required type="email" placeholder="you@yourbusiness.com" className="focus-ring w-full rounded-xl border border-[#ded8cb] bg-[#fbf9f3] px-3.5 py-3.5 text-sm text-[#315f54] outline-none placeholder:text-[#abb3ae]" /></label>{register && <label className="block"><span className="mb-2 block text-[11px] font-bold uppercase tracking-wider text-[#879890]">Business name</span><input data-testid="input-auth-business" required placeholder="Your studio or business" className="focus-ring w-full rounded-xl border border-[#ded8cb] bg-[#fbf9f3] px-3.5 py-3.5 text-sm text-[#315f54] outline-none placeholder:text-[#abb3ae]" /></label>}<label className="block"><span className="mb-2 block text-[11px] font-bold uppercase tracking-wider text-[#879890]">Password</span><div className="relative"><input data-testid="input-auth-password" required type={showPassword ? 'text' : 'password'} placeholder="At least 8 characters" className="focus-ring w-full rounded-xl border border-[#ded8cb] bg-[#fbf9f3] px-3.5 py-3.5 pr-12 text-sm text-[#315f54] outline-none placeholder:text-[#abb3ae]" /><button data-testid="button-toggle-password" type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3.5 text-[#8b9c93]">{showPassword ? <Eye size={17} /> : <LockKeyhole size={16} />}</button></div></label><div className="flex items-center justify-between pt-1">{!register && <label className="flex items-center gap-2 text-[11px] font-bold text-[#7d9087]"><input data-testid="input-remember-me" type="checkbox" className="accent-[#39745a]" />Remember me</label>}{!register && <Link data-testid="link-forgot-password" href="/login" className="text-[11px] font-bold text-[#b66c43]">Forgot password?</Link>}</div><Button type="submit" className="mt-2 w-full py-3.5">{register ? 'Create workspace' : 'Sign in to SahaAI'}<ArrowRight size={15} /></Button></form><div className="my-6 flex items-center gap-3 text-[10px] text-[#abb3ae]"><span className="h-px flex-1 bg-[#e2dcd1]" />OR<span className="h-px flex-1 bg-[#e2dcd1]" /></div><button data-testid="button-google-auth" onClick={() => setLocation('/app')} className="flex w-full items-center justify-center gap-2.5 rounded-xl border border-[#ded8cb] bg-[#fbf9f3] py-3 text-xs font-bold text-[#5f786d] transition hover:bg-[#f0ede4]"><span className="grid size-5 place-items-center rounded-full bg-[#e8d8b8] text-[10px] font-extrabold text-[#7d5b29]">G</span>Continue with Google</button><div className="mt-7 text-center text-xs text-[#819189]">{register ? 'Already have a workspace?' : 'New to SahaAI?'} <Link data-testid="link-auth-switch" href={register ? '/login' : '/register'} className="font-bold text-[#b66c43] hover:text-[#8f4f31]">{register ? 'Sign in' : 'Create an account'}</Link></div></div><div className="mt-8 text-center text-[10px] text-[#a2aca6]">By continuing, you agree to SahaAI's terms and privacy policy.</div></div></div>;
}

