function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={MarketingPage} /><Route path="/login" component={() => <AuthPage />} /><Route path="/register" component={() => <AuthPage register />} /><Route path="/app" component={Overview} /><Route path="/app/inbox" component={InboxPage} /><Route path="/app/contacts" component={ContactsPage} /><Route path="/app/leads" component={LeadsPage} /><Route path="/app/appointments" component={AppointmentsPage} /><Route path="/app/bot-settings" component={BotSettingsPage} /><Route path="/app/flows" component={FlowsPage} /><Route path="/app/analytics" component={AnalyticsPage} /><Route path="/app/business-settings" component={BusinessSettingsPage} /><Route path="/app/whatsapp-settings" component={WhatsAppSettingsPage} /><Route path="/app/billing" component={BillingPage} /><Route component={NotFound} /></Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

